using Microsoft.Extensions.Logging;
using ModelContextProtocol;

// Sample authorization service
public interface IAuthorizationService
{
    Task<bool> HasRoleAsync(string clientId, string requiredRole, CancellationToken ct);
    Task<IReadOnlyList<string>> GetRolesAsync(string clientId, CancellationToken ct);
}

public sealed class McpAuthorizationService : IAuthorizationService
{
    private readonly ILogger<McpAuthorizationService> _logger;

    public McpAuthorizationService(ILogger<McpAuthorizationService> logger)
    {
        _logger = logger;
    }

    public async Task<bool> HasRoleAsync(string clientId, string requiredRole, CancellationToken ct)
    {
        var roles = await GetRolesAsync(clientId, ct);
        return roles.Contains(requiredRole);
    }

    public async Task<IReadOnlyList<string>> GetRolesAsync(string clientId, CancellationToken ct)
    {
        // Simulated role lookup; replace with real identity provider
        await Task.Delay(10, ct);

        return clientId switch
        {
            "client-admin-1" => new[] { "admin", "support" },
            "client-support-1" => new[] { "support" },
            "client-readonly-1" => new[] { "reader" },
            _ => Array.Empty<string>()
        };
    }
}

// Full authorization filter for tool invocation
public sealed class McpAuthorizationFilter
{
    private readonly IAuthorizationService _authorization;
    private readonly ILogger<McpAuthorizationFilter> _logger;

    public McpAuthorizationFilter(IAuthorizationService authorization, ILogger<McpAuthorizationFilter> logger)
    {
        _authorization = authorization;
        _logger = logger;
    }

    public async ValueTask<bool> AuthorizeAsync(
        McpRequestContext context,
        string requiredRole,
        CancellationToken ct = default)
    {
        var clientId = context.Authentication?.ClientId;
        var toolName = context.ToolName ?? "unknown";

        if (string.IsNullOrEmpty(clientId))
        {
            _logger.LogWarning("Unauthenticated access attempted for {Tool}.", toolName);
            // Authorization flow: reject unauthenticated requests
            return false;
        }

        var hasRole = await _authorization.HasRoleAsync(clientId, requiredRole, ct);
        if (!hasRole)
        {
            _logger.LogWarning("Forbidden access: {Tool} for {ClientId}. Required role: {Role}", toolName, clientId, requiredRole);
            // Authorization flow: log and reject
            return false;
        }

        _logger.LogInformation("Authorized access: {Tool} for {ClientId}", toolName, clientId);
        // Authorization flow: allow
        return true;
    }
}

